/* Offline cache for the installed edition. VERSION is regenerated by `node tools/build.mjs` from the asset contents;
   any change to a listed asset produces a new cache and the old one is removed on activation. */
'use strict';
const VERSION='v-1f4a6689';
const CACHE='tiny-civ-'+VERSION;
const ASSETS=["./","index.html","style.css","sim.js","sound.js","app.js","pwa.js","manifest.webmanifest","icons/icon-192.png","icons/icon-512.png","icons/icon-maskable-512.png","icons/apple-touch-icon.png","fonts/dm-sans-latin.woff2","fonts/manrope-latin.woff2"];

// Safari refuses to serve a redirected response for a navigation, so store a clean copy.
async function clean(response){
  if(!response.redirected)return response;
  return new Response(await response.blob(),{status:response.status,statusText:response.statusText,headers:response.headers});
}

self.addEventListener('install',event=>{
  event.waitUntil((async()=>{
    const cache=await caches.open(CACHE);
    for(const url of ASSETS){
      const response=await fetch(new Request(url,{cache:'reload'}));
      if(!response.ok)throw new Error(`Precache failed for ${url}: ${response.status}`);
      await cache.put(url,await clean(response));
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate',event=>{
  event.waitUntil((async()=>{
    for(const key of await caches.keys())if(key.startsWith('tiny-civ-')&&key!==CACHE)await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener('fetch',event=>{
  const request=event.request;
  const url=new URL(request.url);
  if(request.method!=='GET'||url.origin!==location.origin)return;
  event.respondWith((async()=>{
    const cache=await caches.open(CACHE);
    // Launches (the app root or index.html, with any query) open the cached page, so they work without a network.
    const root=new URL('./',location).pathname;
    if(request.mode==='navigate'&&(url.pathname===root||url.pathname===root+'index.html')){
      const page=await cache.match('./')||await cache.match('index.html');
      if(page)return page;
    }
    const hit=await cache.match(request,{ignoreSearch:true});
    return hit||fetch(request);
  })());
});

self.addEventListener('message',event=>{
  if(!event.data||event.data.type!=='status'||!event.ports[0])return;
  event.waitUntil((async()=>{
    const cache=await caches.open(CACHE);
    const found=await Promise.all(ASSETS.map(url=>cache.match(url)));
    const cached=found.filter(Boolean).length;
    event.ports[0].postMessage({version:VERSION,cached,total:ASSETS.length,ready:cached===ASSETS.length});
  })());
});
